const { ShopifyClientError } = require('../errors');

const ARTICLES_QUERY = `
  query($cursor: String) {
    articles(first: 250, after: $cursor) {
      edges {
        node {
          author {
            name
          }
          blog {
            id
            handle
            title
          }
          id
          title
          handle
          body
          image {
            url
            altText
          }
          publishedAt
          tags
        }
      }
      pageInfo {
        hasNextPage
        endCursor
      }
    }
  }
`;

const BLOG_LOOKUP_QUERY = `
  query {
    blogs(first: 250) {
      edges {
        node {
          id
          handle
          title
        }
      }
    }
  }
`;

const ARTICLE_CREATE_MUTATION = `
  mutation articleCreate($article: ArticleCreateInput!) {
    articleCreate(article: $article) {
      article {
        author {
          name
        }
        id
        title
        handle
      }
      userErrors {
        field
        message
      }
    }
  }
`;

const ARTICLE_UPDATE_MUTATION = `
  mutation articleUpdate($id: ID!, $article: ArticleUpdateInput!) {
    articleUpdate(id: $id, article: $article) {
      article {
        author {
          name
        }
        id
        title
        handle
      }
      userErrors {
        field
        message
      }
    }
  }
`;

const ARTICLE_DELETE_MUTATION = `
  mutation deleteArticle($id: ID!) {
    articleDelete(id: $id) {
      deletedArticleId
      userErrors {
        field
        message
      }
    }
  }
`;

function throwOnUserErrors(operation, userErrors) {
  if (!userErrors || userErrors.length === 0) {
    return;
  }

  throw new ShopifyClientError(`${operation} failed`, {
    code: 'SHOPIFY_USER_ERROR',
    details: {
      userErrors
    }
  });
}

function buildArticleInput(articleData, blogId, { includeHandle, includePublishDate } = {}) {
  const input = {
    author: {
      name: articleData.author.name
    },
    title: articleData.title,
    body: articleData.body,
    tags: articleData.tags,
    blogId
  };

  if (includeHandle) {
    input.handle = articleData.handle;
  }

  if (includePublishDate) {
    input.publishDate = articleData.publishedAt;
  }

  if (articleData.image?.url) {
    input.image = {
      url: articleData.image.url,
      altText: articleData.image.altText
    };
  } else if (includePublishDate) {
    input.image = null;
  }

  return input;
}

function createArticlesClient({ graphql }) {
  return {
    async listAll() {
      const articles = [];
      let hasNextPage = true;
      let cursor = null;

      while (hasNextPage) {
        const data = await graphql(ARTICLES_QUERY, { cursor });
        articles.push(...data.articles.edges.map((edge) => edge.node));
        hasNextPage = data.articles.pageInfo.hasNextPage;
        cursor = data.articles.pageInfo.endCursor;
      }

      return articles;
    },

    async listBlogs() {
      const data = await graphql(BLOG_LOOKUP_QUERY, {});
      return data.blogs.edges.map((edge) => edge.node);
    },

    async create(articleData, blogId) {
      const data = await graphql(ARTICLE_CREATE_MUTATION, {
        article: buildArticleInput(articleData, blogId, { includeHandle: true })
      });

      throwOnUserErrors('Article create', data.articleCreate.userErrors);
      return data.articleCreate.article;
    },

    async update(articleId, articleData, blogId) {
      const data = await graphql(ARTICLE_UPDATE_MUTATION, {
        id: articleId,
        article: buildArticleInput(articleData, blogId, { includePublishDate: true })
      });

      throwOnUserErrors('Article update', data.articleUpdate.userErrors);
      return data.articleUpdate.article;
    },

    async delete(articleId) {
      const data = await graphql(ARTICLE_DELETE_MUTATION, { id: articleId });
      throwOnUserErrors('Article delete', data.articleDelete.userErrors);
      return data.articleDelete.deletedArticleId;
    }
  };
}

module.exports = {
  createArticlesClient,
  ARTICLES_QUERY,
  BLOG_LOOKUP_QUERY,
  ARTICLE_CREATE_MUTATION,
  ARTICLE_UPDATE_MUTATION,
  ARTICLE_DELETE_MUTATION
};
